        public static UserSettings Clone(IUserSettings from, bool isDeep = true) 
        {
            Debug.Assert(from != null);
            var vm = new UserSettings(); 
            vm._ListOpenConfigHistory = new ObservableCollectionWithActions<UserSettingsOpenedConfig>(); 
            foreach (var t in from.ListOpenConfigHistory) 
                vm._ListOpenConfigHistory.AddClone(UserSettingsOpenedConfig.Clone((UserSettingsOpenedConfig)t, isDeep));
            if (isDeep) 
                vm._LastAppMainWindowRectOnVirtualScreen = vSharpStudio.vm.ViewModels.RectOnScreen.Clone(from.LastAppMainWindowRectOnVirtualScreen, isDeep);
            vm._LastVirtualScreenWidth = from.LastVirtualScreenWidth; 
            vm._LastVirtualScreenHeight = from.LastVirtualScreenHeight; 
            return vm;
        }
        public static void Update(UserSettings to, IUserSettings from, bool isDeep = true) 
        {
            Debug.Assert(to != null);
            Debug.Assert(from != null);
            if (isDeep) 
            {
                foreach (var t in to.ListOpenConfigHistory.ToList())
                {
                    bool isfound = false;
                    foreach (var tt in from.ListOpenConfigHistory)
                    {
                        if (t.Guid == tt.Guid)
                        {
                            isfound = true;
                            UserSettingsOpenedConfig.Update((UserSettingsOpenedConfig)t, (UserSettingsOpenedConfig)tt, isDeep);
                            break;
                        }
                    }
                    if (!isfound)
                        to.ListOpenConfigHistory.Remove(t);
                }
                foreach (var tt in from.ListOpenConfigHistory)
                {
                    bool isfound = false;
                    foreach (var t in to.ListOpenConfigHistory.ToList())
                    {
                        if (t.Guid == tt.Guid)
                        {
                            isfound = true;
                            break;
                        }
                    }
                    if (!isfound)
                    {
                        var p = new UserSettingsOpenedConfig(); 
                        UserSettingsOpenedConfig.Update(p, (UserSettingsOpenedConfig)tt, isDeep);
                        to.ListOpenConfigHistory.AddClone(p);
                    }
                }
            }
            if (isDeep) 
                vSharpStudio.vm.ViewModels.RectOnScreen.Update((RectOnScreen)to.LastAppMainWindowRectOnVirtualScreen, from.LastAppMainWindowRectOnVirtualScreen, isDeep);
            to._LastVirtualScreenWidth = from.LastVirtualScreenWidth; 
            to._LastVirtualScreenHeight = from.LastVirtualScreenHeight; 
        }
        
