        {
            Debug.Assert(vm != null);
            if (m == null)
            {
                return vm;
            }
            vm._ListOpenConfigHistory = new ObservableCollectionWithActions<UserSettingsOpenedConfig>(); 
            foreach (var t in m.ListOpenConfigHistory) 
            {
                var tvm = UserSettingsOpenedConfig.ConvertToVM(t, new UserSettingsOpenedConfig()); 
                vm.ListOpenConfigHistory.Add(tvm);
            }
            vm.LastAppMainWindowRectOnVirtualScreen ??= new RectOnScreen(); 
            vSharpStudio.vm.ViewModels.RectOnScreen.ConvertToVM(m.LastAppMainWindowRectOnVirtualScreen, (RectOnScreen)vm.LastAppMainWindowRectOnVirtualScreen); 
            vm._LastVirtualScreenWidth = m.LastVirtualScreenWidth; 
            vm._LastVirtualScreenHeight = m.LastVirtualScreenHeight; 
            return vm;
        }
        // Conversion from 'UserSettings' to 'proto_user_settings'
        public static Proto.Config.proto_user_settings ConvertToProto(UserSettings vm) 
        {
            Debug.Assert(vm != null);
            Proto.Config.proto_user_settings m = new Proto.Config.proto_user_settings(); 
            foreach (var t in vm.ListOpenConfigHistory) 
                m.ListOpenConfigHistory.Add(UserSettingsOpenedConfig.ConvertToProto((UserSettingsOpenedConfig)t)); 
            m.LastAppMainWindowRectOnVirtualScreen = vSharpStudio.vm.ViewModels.RectOnScreen.ConvertToProto((RectOnScreen)vm.LastAppMainWindowRectOnVirtualScreen); 
            m.LastVirtualScreenWidth = vm.LastVirtualScreenWidth; 
            m.LastVirtualScreenHeight = vm.LastVirtualScreenHeight; 
            return m;
        }
        
        public void AcceptConfigNodeVisitor(ConfigVisitor visitor) 
        {
            Debug.Assert(visitor != null);
            if (visitor.Token.IsCancellationRequested)
            {
                return;
            }
            visitor.Visit(this);
            foreach (var t in this.ListOpenConfigHistory) 
            {
                t.AcceptConfigNodeVisitor(visitor);
            }
            this.LastAppMainWindowRectOnVirtualScreen.AcceptConfigNodeVisitor(visitor); 
        
            visitor.VisitEnd(this); 
        }
