            var mes = t.Name + ":";
            var p = t.GetProperty("Name");
            if (p != null)
                mes = mes + (string?)p.GetValue(this) + ":";
            p = t.GetProperty("IsNew");
            if (p != null)
                if ((bool?)p.GetValue(this) == true)
                    mes = mes + " New";
            p = t.GetProperty("IsHasNew");
            if (p != null)
                if ((bool?)p.GetValue(this) == true)
                    mes = mes + " HasNew";
            OnDebugStringExtend(ref mes);
            return mes + base.ToDebugString();
        }
