        #region CTOR
        public AppSolution(ITreeConfigNode? parent) 
            : base(parent, AppSolutionValidator.Validator)
        {
            //Debug.Assert(/*!VmBindable.isUnitTests*/ this is IDataType || this is IConfig || parent != null);
            this.OnCreating();
