        public static AppSolution Clone(ITreeConfigNode? parent, IAppSolution from, bool isDeep = true, bool isNewGuid = false) 
        {
            Debug.Assert(from != null);
            var vm = new AppSolution(parent); 
            vm._Guid = from.Guid; 
            vm._Name = from.Name; 
            vm._NameUi = from.NameUi; 
            vm._ExplicitSortingPosition = from.ExplicitSortingPosition; 
            vm._Description = from.Description; 
            vm._SortType = from.SortType; 
            vm._ShortIdForCacheKey = from.ShortIdForCacheKey; 
            vm._RelativeAppSolutionPath = from.RelativeAppSolutionPath; 
            vm._IsNew = from.IsNew; 
            vm._IsMarkedForDeletion = from.IsMarkedForDeletion; 
            vm._ListAppProjects = new ConfigNodesCollection<AppProject>(vm); 
            foreach (var t in from.ListAppProjects) 
                vm._ListAppProjects.AddClone(AppProject.Clone(vm, (AppProject)t, isDeep));
            vm._ListGeneratorsSolutionSettings = new ObservableCollectionWithActions<PluginGeneratorSolutionSettings>(); 
            foreach (var t in from.ListGeneratorsSolutionSettings) 
                vm._ListGeneratorsSolutionSettings.AddClone(PluginGeneratorSolutionSettings.Clone(parent, (PluginGeneratorSolutionSettings)t, isDeep));
            return vm;
        }
        public static void Update(AppSolution to, IAppSolution from, bool isDeep = true) 
        {
            Debug.Assert(to != null);
            Debug.Assert(from != null);
            to._Guid = from.Guid; 
            to._Name = from.Name; 
            to._NameUi = from.NameUi; 
            to._ExplicitSortingPosition = from.ExplicitSortingPosition; 
            to._Description = from.Description; 
            to._SortType = from.SortType; 
            to._ShortIdForCacheKey = from.ShortIdForCacheKey; 
            to._RelativeAppSolutionPath = from.RelativeAppSolutionPath; 
            to._IsNew = from.IsNew; 
            to._IsMarkedForDeletion = from.IsMarkedForDeletion; 
            if (isDeep) 
            {
                foreach (var t in to.ListAppProjects.ToList())
                {
                    bool isfound = false;
                    foreach (var tt in from.ListAppProjects)
                    {
                        if (t.Guid == tt.Guid)
                        {
                            isfound = true;
                            AppProject.Update((AppProject)t, (AppProject)tt, isDeep);
                            break;
                        }
                    }
                    if (!isfound)
                        to.ListAppProjects.Remove(t);
                }
                foreach (var tt in from.ListAppProjects)
                {
                    bool isfound = false;
                    foreach (var t in to.ListAppProjects.ToList())
                    {
                        if (t.Guid == tt.Guid)
                        {
                            isfound = true;
                            break;
                        }
                    }
                    if (!isfound)
                    {
                        var p = new AppProject(to); 
                        AppProject.Update(p, (AppProject)tt, isDeep);
                        to.ListAppProjects.AddClone(p);
                    }
                }
            }
            if (isDeep) 
            {
                foreach (var t in to.ListGeneratorsSolutionSettings.ToList())
                {
                    bool isfound = false;
                    foreach (var tt in from.ListGeneratorsSolutionSettings)
                    {
                        if (t.Guid == tt.Guid)
                        {
                            isfound = true;
                            PluginGeneratorSolutionSettings.Update((PluginGeneratorSolutionSettings)t, (PluginGeneratorSolutionSettings)tt, isDeep);
                            break;
                        }
                    }
                    if (!isfound)
                        to.ListGeneratorsSolutionSettings.Remove(t);
                }
                foreach (var tt in from.ListGeneratorsSolutionSettings)
                {
                    bool isfound = false;
                    foreach (var t in to.ListGeneratorsSolutionSettings.ToList())
                    {
                        if (t.Guid == tt.Guid)
                        {
                            isfound = true;
                            break;
                        }
                    }
                    if (!isfound)
                    {
                        var p = new PluginGeneratorSolutionSettings(to); 
                        PluginGeneratorSolutionSettings.Update(p, (PluginGeneratorSolutionSettings)tt, isDeep);
                        to.ListGeneratorsSolutionSettings.AddClone(p);
                    }
                }
            }
        }
        
