        // Conversion from 'proto_app_solution' to 'AppSolution'
        public static AppSolution ConvertToVM(Proto.Config.proto_app_solution m, AppSolution vm) 
        {
            Debug.Assert(vm != null);
            if (m == null)
            {
                return vm;
            }
            vm._Guid = m.Guid; 
            vm._Name = m.Name; 
            vm._NameUi = m.NameUi; 
            vm._ExplicitSortingPosition = m.ExplicitSortingPosition; 
            vm._Description = m.Description; 
            vm._SortType = (EnumSortingType)m.SortType; 
            vm._ShortIdForCacheKey = m.ShortIdForCacheKey; 
            vm._RelativeAppSolutionPath = m.RelativeAppSolutionPath; 
            vm._IsNew = m.IsNew; 
            vm._IsMarkedForDeletion = m.IsMarkedForDeletion; 
            vm._ListAppProjects = new ConfigNodesCollection<AppProject>(vm); 
            foreach (var t in m.ListAppProjects) 
            {
                var tvm = AppProject.ConvertToVM(t, new AppProject(vm)); 
                vm.ListAppProjects.Add(tvm);
            }
            vm._ListGeneratorsSolutionSettings = new ObservableCollectionWithActions<PluginGeneratorSolutionSettings>(); 
            foreach (var t in m.ListGeneratorsSolutionSettings) 
            {
                var tvm = PluginGeneratorSolutionSettings.ConvertToVM(t, new PluginGeneratorSolutionSettings(vm)); 
                vm.ListGeneratorsSolutionSettings.Add(tvm);
            }
            vm.OnInitFromDto(); 
            vm.IsChanged = false;
            vm.IsHasChanged = false;
            return vm;
        }
        // Conversion from 'AppSolution' to 'proto_app_solution'
        public static Proto.Config.proto_app_solution ConvertToProto(AppSolution vm) 
        {
            Debug.Assert(vm != null);
            Proto.Config.proto_app_solution m = new Proto.Config.proto_app_solution(); 
            try 
            { 
                m.Guid = System.Text.Encoding.UTF8.GetString(System.Text.Encoding.Default.GetBytes(vm.Guid)); 
