            }
            catch (Exception ex) 
            { 
                throw new Exception("Error while converting to PROTO and encoding from Default to UTF8. For 'vsharpstudio.proto' message 'proto_app_solution' field 'name'", ex); 
            }
            try 
            { 
                m.NameUi = System.Text.Encoding.UTF8.GetString(System.Text.Encoding.Default.GetBytes(vm.NameUi)); 
            }
            catch (Exception ex) 
            { 
                throw new Exception("Error while converting to PROTO and encoding from Default to UTF8. For 'vsharpstudio.proto' message 'proto_app_solution' field 'name_ui'", ex); 
            }
            m.ExplicitSortingPosition = vm.ExplicitSortingPosition; 
            try 
            { 
                m.Description = System.Text.Encoding.UTF8.GetString(System.Text.Encoding.Default.GetBytes(vm.Description)); 
            }
            catch (Exception ex) 
            { 
                throw new Exception("Error while converting to PROTO and encoding from Default to UTF8. For 'vsharpstudio.proto' message 'proto_app_solution' field 'description'", ex); 
            }
            m.SortType = (Proto.Config.proto_enum_sorting_type)vm.SortType; 
            try 
            { 
                m.ShortIdForCacheKey = System.Text.Encoding.UTF8.GetString(System.Text.Encoding.Default.GetBytes(vm.ShortIdForCacheKey)); 
            }
            catch (Exception ex) 
            { 
                throw new Exception("Error while converting to PROTO and encoding from Default to UTF8. For 'vsharpstudio.proto' message 'proto_app_solution' field 'short_id_for_cache_key'", ex); 
            }
            try 
            { 
                m.RelativeAppSolutionPath = System.Text.Encoding.UTF8.GetString(System.Text.Encoding.Default.GetBytes(vm.RelativeAppSolutionPath)); 
            }
            catch (Exception ex) 
            { 
                throw new Exception("Error while converting to PROTO and encoding from Default to UTF8. For 'vsharpstudio.proto' message 'proto_app_solution' field 'relative_app_solution_path'", ex); 
            }
            m.IsNew = vm.IsNew; 
            m.IsMarkedForDeletion = vm.IsMarkedForDeletion; 
            foreach (var t in vm.ListAppProjects) 
                m.ListAppProjects.Add(AppProject.ConvertToProto((AppProject)t)); 
            foreach (var t in vm.ListGeneratorsSolutionSettings) 
                m.ListGeneratorsSolutionSettings.Add(PluginGeneratorSolutionSettings.ConvertToProto((PluginGeneratorSolutionSettings)t)); 
            return m;
        }
        
        public void AcceptConfigNodeVisitor(ConfigVisitor visitor) 
        {
            Debug.Assert(visitor != null);
            if (visitor.Token.IsCancellationRequested)
            {
                return;
            }
            visitor.Visit(this);
            foreach (var t in this.ListAppProjects) 
            {
                t.AcceptConfigNodeVisitor(visitor);
            }
            foreach (var t in this.ListGeneratorsSolutionSettings) 
            {
                t.AcceptConfigNodeVisitor(visitor);
            }
            visitor.VisitEnd(this); 
        }
