        public static DataType Clone(ITreeConfigNode? parent, IDataType from, bool isDeep = true) 
        {
            Debug.Assert(from != null);
            var vm = new DataType(parent); 
            vm._DataTypeEnum = from.DataTypeEnum; 
            vm._IsUnicode = from.IsUnicode; 
            vm._Length = from.Length; 
            vm._IsPositive = from.IsPositive; 
            vm._Accuracy = from.Accuracy; 
            vm._AccuracyForTime = from.AccuracyForTime; 
            vm._ListObjectRefs = new ObservableCollectionWithActions<ComplexRef>(); 
            foreach (var t in from.ListObjectRefs) 
                vm._ListObjectRefs.AddClone(ComplexRef.Clone((ComplexRef)t, isDeep));
            vm._IsNullable = from.IsNullable; 
            vm._TimespanAccuracy = from.TimespanAccuracy; 
            vm._TimespanMaxValue = from.TimespanMaxValue; 
            vm._IsUseHistory = from.IsUseHistory; 
            vm._IsPKey = from.IsPKey; 
            vm._IsRefParent = from.IsRefParent; 
            return vm;
        }
        public static void Update(DataType to, IDataType from, bool isDeep = true) 
        {
            Debug.Assert(to != null);
            Debug.Assert(from != null);
            to._DataTypeEnum = from.DataTypeEnum; 
            to._IsUnicode = from.IsUnicode; 
            to._Length = from.Length; 
            to._IsPositive = from.IsPositive; 
            to._Accuracy = from.Accuracy; 
            to._AccuracyForTime = from.AccuracyForTime; 
            if (isDeep) 
            {
                foreach (var t in to.ListObjectRefs.ToList())
                {
                    bool isfound = false;
                    foreach (var tt in from.ListObjectRefs)
                    {
                        if (t.Guid == tt.Guid)
                        {
                            isfound = true;
                            ComplexRef.Update((ComplexRef)t, (ComplexRef)tt, isDeep);
                            break;
                        }
                    }
                    if (!isfound)
                        to.ListObjectRefs.Remove(t);
                }
                foreach (var tt in from.ListObjectRefs)
                {
                    bool isfound = false;
                    foreach (var t in to.ListObjectRefs.ToList())
                    {
                        if (t.Guid == tt.Guid)
                        {
                            isfound = true;
                            break;
                        }
                    }
                    if (!isfound)
                    {
                        var p = new ComplexRef(); 
                        ComplexRef.Update(p, (ComplexRef)tt, isDeep);
                        to.ListObjectRefs.AddClone(p);
                    }
                }
            }
            to._IsNullable = from.IsNullable; 
            to._TimespanAccuracy = from.TimespanAccuracy; 
            to._TimespanMaxValue = from.TimespanMaxValue; 
            to._IsUseHistory = from.IsUseHistory; 
            to._IsPKey = from.IsPKey; 
            to._IsRefParent = from.IsRefParent; 
        }
        
