            }
            vm._DataTypeEnum = (EnumDataType)m.DataTypeEnum; 
            vm._IsUnicode = m.IsUnicode; 
            vm._Length = m.Length; 
            vm._IsPositive = m.IsPositive; 
            vm._Accuracy = m.Accuracy; 
            vm._AccuracyForTime = (EnumTimeAccuracyType)m.AccuracyForTime; 
            vm._ListObjectRefs = new ObservableCollectionWithActions<ComplexRef>(); 
            foreach (var t in m.ListObjectRefs) 
