            Proto.Config.proto_data_type m = new Proto.Config.proto_data_type(); 
            m.DataTypeEnum = (Proto.Config.proto_enum_data_type)vm.DataTypeEnum; 
            m.IsUnicode = vm.IsUnicode; 
            m.Length = vm.Length; 
            m.IsPositive = vm.IsPositive; 
            m.Accuracy = vm.Accuracy; 
