            {
                t.AcceptConfigNodeVisitor(visitor);
            }
            foreach (var t in this.ListNodeGeneratorsSettings) 
            {
                t.AcceptConfigNodeVisitor(visitor);
            }
            visitor.VisitEnd(this); 
        }
