        public static Constant Clone(ITreeConfigNode? parent, IConstant from, bool isDeep = true, bool isNewGuid = false) 
        {
            Debug.Assert(from != null);
            var vm = new Constant(parent); 
            vm._Guid = from.Guid; 
            vm._Name = from.Name; 
            vm._ExplicitSortingPosition = from.ExplicitSortingPosition; 
            vm._NameUi = from.NameUi; 
            vm._Description = from.Description; 
            if (isDeep) 
                vm._DataType = vSharpStudio.vm.ViewModels.DataType.Clone(vm, from.DataType, isDeep);
            vm._IsNullable = from.IsNullable; 
            vm._DefaultValue = from.DefaultValue; 
            vm._IsNew = from.IsNew; 
            vm._IsMarkedForDeletion = from.IsMarkedForDeletion; 
            vm._ShortId = from.ShortId; 
            vm._ShortRefId = from.ShortRefId; 
            vm._RangeValuesRequirementStr = from.RangeValuesRequirementStr; 
            vm._MinLengthRequirement = from.MinLengthRequirement; 
            vm._MaxLengthRequirement = from.MaxLengthRequirement; 
            vm._AccuracyForTime = from.AccuracyForTime; 
            vm._IsTryAttach = from.IsTryAttach; 
            vm._LinesOnScreen = from.LinesOnScreen; 
            vm._IsStartNewRow = from.IsStartNewRow; 
            vm._TabName = from.TabName; 
            vm._IsStartNewTabControl = from.IsStartNewTabControl; 
            vm._IsStopTabControl = from.IsStopTabControl; 
            vm._ListRoleConstantAccessSettings = new ObservableCollectionWithActions<RoleConstantAccess>(); 
            foreach (var t in from.ListRoleConstantAccessSettings) 
                vm._ListRoleConstantAccessSettings.AddClone(RoleConstantAccess.Clone((RoleConstantAccess)t, isDeep));
            vm._RefComplexObjectGdPropertyGuid = from.RefComplexObjectGdPropertyGuid; 
            vm._RefComplexObjectDescrPropertyGuid = from.RefComplexObjectDescrPropertyGuid; 
            vm._PositionOfGd = from.PositionOfGd; 
            vm._PositionOfDescr = from.PositionOfDescr; 
            vm._Position = from.Position; 
            vm._ListNodeGeneratorsSettings = new ConfigNodesCollection<PluginGeneratorNodeSettings>(vm); 
            foreach (var t in from.ListNodeGeneratorsSettings) 
                vm._ListNodeGeneratorsSettings.AddClone(PluginGeneratorNodeSettings.Clone(vm, (PluginGeneratorNodeSettings)t, isDeep));
            if (isNewGuid) 
                vm.SetNewGuid();
            return vm;
        }
        public static void Update(Constant to, IConstant from, bool isDeep = true) 
        {
            Debug.Assert(to != null);
            Debug.Assert(from != null);
            to._Guid = from.Guid; 
            to._Name = from.Name; 
            to._ExplicitSortingPosition = from.ExplicitSortingPosition; 
            to._NameUi = from.NameUi; 
            to._Description = from.Description; 
            if (isDeep) 
                vSharpStudio.vm.ViewModels.DataType.Update((DataType)to.DataType, from.DataType, isDeep);
            to._IsNullable = from.IsNullable; 
            to._DefaultValue = from.DefaultValue; 
            to._IsNew = from.IsNew; 
            to._IsMarkedForDeletion = from.IsMarkedForDeletion; 
            to._ShortId = from.ShortId; 
            to._ShortRefId = from.ShortRefId; 
            to._RangeValuesRequirementStr = from.RangeValuesRequirementStr; 
            to._MinLengthRequirement = from.MinLengthRequirement; 
            to._MaxLengthRequirement = from.MaxLengthRequirement; 
            to._AccuracyForTime = from.AccuracyForTime; 
            to._IsTryAttach = from.IsTryAttach; 
            to._LinesOnScreen = from.LinesOnScreen; 
            to._IsStartNewRow = from.IsStartNewRow; 
            to._TabName = from.TabName; 
            to._IsStartNewTabControl = from.IsStartNewTabControl; 
            to._IsStopTabControl = from.IsStopTabControl; 
            if (isDeep) 
            {
                foreach (var t in to.ListRoleConstantAccessSettings.ToList())
                {
                    bool isfound = false;
                    foreach (var tt in from.ListRoleConstantAccessSettings)
                    {
                        if (t.Guid == tt.Guid)
                        {
                            isfound = true;
                            RoleConstantAccess.Update((RoleConstantAccess)t, (RoleConstantAccess)tt, isDeep);
                            break;
                        }
                    }
                    if (!isfound)
                        to.ListRoleConstantAccessSettings.Remove(t);
                }
                foreach (var tt in from.ListRoleConstantAccessSettings)
                {
                    bool isfound = false;
                    foreach (var t in to.ListRoleConstantAccessSettings.ToList())
                    {
                        if (t.Guid == tt.Guid)
                        {
                            isfound = true;
                            break;
                        }
                    }
                    if (!isfound)
                    {
                        var p = new RoleConstantAccess(); 
                        RoleConstantAccess.Update(p, (RoleConstantAccess)tt, isDeep);
                        to.ListRoleConstantAccessSettings.AddClone(p);
                    }
                }
            }
            to._RefComplexObjectGdPropertyGuid = from.RefComplexObjectGdPropertyGuid; 
            to._RefComplexObjectDescrPropertyGuid = from.RefComplexObjectDescrPropertyGuid; 
            to._PositionOfGd = from.PositionOfGd; 
            to._PositionOfDescr = from.PositionOfDescr; 
            to._Position = from.Position; 
            if (isDeep) 
            {
                foreach (var t in to.ListNodeGeneratorsSettings.ToList())
                {
                    bool isfound = false;
                    foreach (var tt in from.ListNodeGeneratorsSettings)
                    {
                        if (t.Guid == tt.Guid)
                        {
                            isfound = true;
                            PluginGeneratorNodeSettings.Update((PluginGeneratorNodeSettings)t, (PluginGeneratorNodeSettings)tt, isDeep);
                            break;
