        public void AcceptConfigNodeVisitor(ConfigVisitor visitor) 
        {
            Debug.Assert(visitor != null);
            if (visitor.Token.IsCancellationRequested)
            {
                return;
            }
            visitor.Visit(this);
            this.GroupRegisterDimensions.AcceptConfigNodeVisitor(visitor); 
        
            this.GroupProperties.AcceptConfigNodeVisitor(visitor); 
        
            foreach (var t in this.ListObjectDocRefs) 
            {
                t.AcceptConfigNodeVisitor(visitor);
            }
            this.PropertyRefTimeline.AcceptConfigNodeVisitor(visitor); 
        
            this.GroupReports.AcceptConfigNodeVisitor(visitor); 
        
            foreach (var t in this.ListNodeGeneratorsSettings) 
            {
                t.AcceptConfigNodeVisitor(visitor);
            }
            visitor.VisitEnd(this); 
        }
