        public static void Update(RelationManyToMany to, IRelationManyToMany from, bool isDeep = true) 
        {
            Debug.Assert(to != null);
            Debug.Assert(from != null);
            to._Guid = from.Guid; 
            to._Name = from.Name; 
            to._ExplicitSortingPosition = from.ExplicitSortingPosition; 
            to._NameUi = from.NameUi; 
            to._Description = from.Description; 
            to._RefObj1Type = from.RefObj1Type; 
