        public static void Update(Form to, IForm from, bool isDeep = true) 
        {
            Debug.Assert(to != null);
            Debug.Assert(from != null);
            to._Guid = from.Guid; 
            to._Name = from.Name; 
            to._ExplicitSortingPosition = from.ExplicitSortingPosition; 
            to._NameUi = from.NameUi; 
            to._Description = from.Description; 
            to._IsNew = from.IsNew; 
            to._IsMarkedForDeletion = from.IsMarkedForDeletion; 
            to._IsUseCode = from.IsUseCode; 
            to._IsUseName = from.IsUseName; 
            to._IsUseDesc = from.IsUseDesc; 
            to._IsUseFolderCode = from.IsUseFolderCode; 
            to._IsUseFolderName = from.IsUseFolderName; 
            to._IsUseFolderDesc = from.IsUseFolderDesc; 
            to._IsUseDocDate = from.IsUseDocDate; 
            to._IsDummy = from.IsDummy; 
            to._EnumFormType = from.EnumFormType; 
            if (isDeep) 
                vSharpStudio.vm.ViewModels.FormGridSystem.Update((FormGridSystem)to.GridSystem, from.GridSystem, isDeep);
                to.ListGuidViewProperties.Clear(); 
                foreach (var tt in from.ListGuidViewProperties)
                {
                    to.ListGuidViewProperties.Add(tt);
                }
                to.ListGuidViewFolderProperties.Clear(); 
                foreach (var tt in from.ListGuidViewFolderProperties)
                {
                    to.ListGuidViewFolderProperties.Add(tt);
                }
            if (isDeep) 
            {
                foreach (var t in to.ListNodeGeneratorsSettings.ToList())
                {
                    bool isfound = false;
                    foreach (var tt in from.ListNodeGeneratorsSettings)
                    {
                        if (t.Guid == tt.Guid)
                        {
                            isfound = true;
                            PluginGeneratorNodeSettings.Update((PluginGeneratorNodeSettings)t, (PluginGeneratorNodeSettings)tt, isDeep);
                            break;
                        }
                    }
                    if (!isfound)
                        to.ListNodeGeneratorsSettings.Remove(t);
                }
                foreach (var tt in from.ListNodeGeneratorsSettings)
                {
                    bool isfound = false;
                    foreach (var t in to.ListNodeGeneratorsSettings.ToList())
                    {
                        if (t.Guid == tt.Guid)
                        {
                            isfound = true;
                            break;
                        }
                    }
                    if (!isfound)
                    {
                        var p = new PluginGeneratorNodeSettings(to); 
                        PluginGeneratorNodeSettings.Update(p, (PluginGeneratorNodeSettings)tt, isDeep);
                        to.ListNodeGeneratorsSettings.AddClone(p);
                    }
                }
            }
        }
        
